S['CH0112A'] = [{'k': 'hook', 'ch': 'Mở đầu', 'label': 'Vietcombank', 'cap': ('TRẢ 6,8%', 'VẪN LÃI 41.000 TỶ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'bank building Hanoi', 'chart': {'sym': 'VCBW', 'tf': 'W', 'weeks': 52, 'circles': [[9, 78.15, 'Đỉnh tuần 12/1/26: 78,15', 0.6], [35, 52.6, 'Đáy tuần 20/7/26: 52,60', 1.6], [51, 54.1, 'Tuần 9/11/26: 54,10', 2.6]]}, 'say': 'Anh chị gửi một tỷ đồng vào ngân hàng mười hai tháng. Lãi suất niêm yết gần đây khoảng sáu phẩy tám phần trăm, cuối năm anh chị nhận về sáu mươi tám triệu. Nghe như ngân hàng đang trả cho mình rất hậu. Nhưng cũng trong mười hai tháng gần nhất, riêng Vietcombank lãi khoảng bốn mươi mốt nghìn tỷ đồng. Trả lãi cao như vậy mà vẫn lãi lớn như vậy, thì tiền đó đến từ đâu? Câu trả lời nằm ngay trong cái ứng dụng ngân hàng trên điện thoại của anh chị. Xem hết video này, anh chị sẽ biết ngân hàng kiếm tiền từ mình bằng cách nào, và con số nào cho thấy ngân hàng nào giỏi hơn. Cuối video là cách để đứng cùng phía với ngân hàng, thay vì chỉ là người gửi tiền.'}, {'k': 'bignum', 'ch': 'Chương 1 – Cỗ máy 430 nghìn tỷ', 'cap': ('7 NGÂN HÀNG LỚN', 'THU LÃI THUẦN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 430, 'fmt': '{:,.0f}', 'unit': ' nghìn tỷ', 'top': '12 THÁNG ĐẾN QUÝ 3/2026', 'sub': '≈ 1.178 tỷ mỗi ngày', 'col': (255, 196, 0), 'say': 'Bắt đầu bằng một con số cho dễ hình dung. Em cộng bảy ngân hàng lớn là Vietcombank, BIDV, VietinBank, MB, Techcombank, ACB và VPBank. Tính mười hai tháng đến hết quý ba năm nay, bảy ngân hàng này thu lãi nhiều hơn trả lãi khoảng bốn trăm ba mươi nghìn tỷ đồng. Phần chênh lệch đó gọi là thu nhập lãi thuần. Chia ra mỗi ngày, kể cả thứ Bảy, Chủ nhật, là khoảng một nghìn một trăm bảy mươi tám tỷ đồng. Và nguyên liệu chính của cỗ máy này là khoảng chín phẩy một triệu tỷ đồng tiền gửi của khách hàng, tức là tiền của những người như anh chị và em.'}, {'k': 'text', 'ch': 'Chương 2 – Tiệm mua tiền rẻ, bán tiền đắt', 'cap': ('MUA TIỀN RẺ', 'BÁN TIỀN ĐẮT'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'rice shop Vietnam market', 'say': 'Hãy nghĩ ngân hàng giống một tiệm gạo. Tiệm gạo nhập gạo giá thấp, bán ra giá cao hơn, phần chênh là tiền lời. Ngân hàng cũng vậy, chỉ có điều món hàng là tiền. Ngân hàng mua tiền của người gửi, rồi bán tiền đó cho người vay. Vậy ngân hàng mua tiền của anh chị với giá bao nhiêu? Nhiều người sẽ trả lời là sáu đến bảy phần trăm một năm. Đó là con số dán trên bảng lãi suất. Nhưng đây là chỗ thú vị nhất, và cũng là chỗ phần lớn người gửi tiền không để ý.'}, {'k': 'cards', 'ch': 'Chương 3 – Con số ngân hàng không dán lên bảng', 'cap': ('GIÁ VỐN THẬT', 'CỦA VIETCOMBANK'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'anh': 'calculator money', 'cards': [('Lãi thu trên tài sản sinh lãi', '5,48%', ''), ('Chi phí vốn bình quân', '2,84%', ''), ('Biên lãi thuần NIM', '2,93%', '')], 'say': 'Theo báo cáo tài chính mười hai tháng gần nhất của Vietcombank, mỗi một trăm đồng tài sản sinh lãi mang về khoảng năm phẩy bốn mươi tám đồng tiền lãi một năm. Trong khi đó, chi phí vốn bình quân, tức là giá trung bình ngân hàng phải trả cho mỗi một trăm đồng vốn huy động, chỉ khoảng hai phẩy tám mươi bốn đồng. Nhưng có một điều lạ ở đây. Lãi tiết kiệm mười hai tháng niêm yết gần đây là sáu phẩy tám phần trăm, vậy sao giá vốn bình quân chỉ có hai phẩy tám mươi bốn phần trăm? Thậm chí nếu toàn bộ tiền huy động đều phải trả sáu phẩy tám phần trăm, thì với mức thu năm phẩy bốn mươi tám phần trăm, ngân hàng sẽ lỗ. Vậy là có một nguồn tiền rất rẻ đang kéo giá vốn xuống. Và nguồn tiền đó, nhiều khả năng đang nằm trong tài khoản của chính anh chị.'}, {'k': 'bignum', 'ch': 'Chương 4 – Bí mật trong tài khoản thanh toán', 'cap': ('TIỀN KHÔNG KỲ HẠN', 'CỦA VIETCOMBANK'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 32.2, 'fmt': '{:,.1f}', 'unit': '%', 'top': 'TỶ LỆ CASA QUÝ 3/2026', 'sub': '≈ 573 nghìn tỷ lãi gần bằng 0', 'col': (34, 197, 94), 'say': 'Bí mật thứ nhất có tên là CASA, tức là tiền gửi không kỳ hạn, chính là số dư trong tài khoản thanh toán mà anh chị dùng để nhận lương, chuyển khoản, quẹt mã QR. Ở Vietcombank, loại tiền này chiếm khoảng ba mươi hai phẩy hai phần trăm tổng tiền gửi, tương đương khoảng năm trăm bảy mươi ba nghìn tỷ đồng. Lãi suất không kỳ hạn thường chỉ khoảng không phẩy một phần trăm một năm. Nghĩa là cứ mười đồng anh chị để trong tài khoản thanh toán, ngân hàng gần như được dùng miễn phí. Số tiền anh chị để đó chờ tiêu, cộng với hàng triệu người khác, trở thành nguồn vốn rẻ nhất mà ngân hàng có. Đây là lý do các ngân hàng đua nhau miễn phí chuyển khoản, tặng tài khoản số đẹp: họ không làm từ thiện, họ đang mua tiền rẻ.'}, {'k': 'bars', 'ch': 'Chương 4 – Bí mật trong tài khoản thanh toán', 'cap': ('AI GIỮ ĐƯỢC', 'TIỀN RẺ NHẤT?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'bars': [('MBB', 34.0, (34, 197, 94), '34,0%'), ('TCB', 32.5, (34, 197, 94), '32,5%'), ('VCB', 32.2, (34, 197, 94), '32,2%'), ('CTG', 23.1, (56, 189, 248), '23,1%'), ('BID', 20.1, (56, 189, 248), '20,1%'), ('ACB', 19.9, (56, 189, 248), '19,9%'), ('VPB', 12.9, (239, 68, 68), '12,9%')], 'say': 'So bảy ngân hàng, MB dẫn đầu với tỷ lệ tiền không kỳ hạn khoảng ba mươi bốn phần trăm, Techcombank khoảng ba mươi hai phẩy năm phần trăm, Vietcombank ba mươi hai phẩy hai phần trăm. Nhóm giữa là VietinBank, BIDV và ACB, quanh hai mươi đến hai mươi ba phần trăm. VPBank thấp nhất, khoảng mười hai phẩy chín phần trăm. Con số này không chỉ là chuyện thống kê. Ngân hàng nào giữ được nhiều tiền rẻ, ngân hàng đó có lợi thế về giá vốn, giống như tiệm gạo nhập được hàng rẻ hơn đối thủ. Và lợi thế đó thường bền, vì người ta ít khi đổi ngân hàng nhận lương.'}, {'k': 'bars', 'ch': 'Chương 5 – Ai bán tiền đắt nhất?', 'cap': ('BIÊN LÃI THUẦN', 'NIM 12 THÁNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'bars': [('VPB', 5.15, (255, 196, 0), '5,15%'), ('MBB', 4.16, (255, 196, 0), '4,16%'), ('TCB', 3.67, (56, 189, 248), '3,67%'), ('ACB', 2.99, (56, 189, 248), '2,99%'), ('VCB', 2.93, (56, 189, 248), '2,93%'), ('CTG', 2.84, (56, 189, 248), '2,84%'), ('BID', 2.16, (56, 189, 248), '2,16%')], 'say': 'Vế còn lại là bán tiền. Thước đo quan trọng nhất ở đây là biên lãi thuần, viết tắt là NIM, tức là mỗi một trăm đồng tài sản sinh lãi để lại bao nhiêu đồng chênh lệch. Và đây là một bất ngờ. VPBank, ngân hàng có tiền rẻ ít nhất, lại có biên lãi cao nhất, khoảng năm phẩy mười lăm phần trăm. MB khoảng bốn phẩy mười sáu phần trăm. Còn Vietcombank, ngân hàng có giá vốn rẻ nhất, biên lãi chỉ khoảng hai phẩy chín mươi ba phần trăm, và BIDV thấp nhất, khoảng hai phẩy mười sáu phần trăm. Vốn đắt mà vẫn lời nhiều hơn, VPBank làm thế nào? Câu trả lời nằm ở việc họ bán tiền cho ai.'}, {'k': 'cards', 'ch': 'Chương 6 – Lãi cao luôn có giá của nó', 'cap': ('NỢ XẤU', 'TRÊN DƯ NỢ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'anh': 'warning sign', 'cards': [('VPBank: nợ xấu / cho vay', '≈ 3,1%', ''), ('Vietcombank: nợ xấu / cho vay', '≈ 0,7%', ''), ('Lãi thu VPB so với VCB', '10,07% / 5,48%', '')], 'say': 'VPBank thu lãi trên tài sản khoảng mười phẩy không bảy phần trăm một năm, gần gấp đôi Vietcombank, vì họ cho vay nhiều ở mảng tiêu dùng và khách hàng cá nhân, nơi lãi suất cao. Nhưng lãi cao luôn có giá của nó. Tính theo số dư quý ba năm hai nghìn không trăm hai mươi sáu, nợ xấu của VPBank khoảng ba mươi bảy phẩy tám nghìn tỷ, bằng khoảng ba phẩy một phần trăm dư nợ cho vay. Vietcombank cho vay nhiều hơn VPBank, nhưng nợ xấu chỉ khoảng mười hai phẩy tám nghìn tỷ, tương đương khoảng không phẩy bảy phần trăm dư nợ. Một bên chọn bán tiền đắt cho khách rủi ro hơn, một bên chọn bán rẻ cho khách an toàn hơn. Không có cách nào đúng tuyệt đối. Và anh chị để ý: đây cũng chính là bài toán của người đầu tư. Lợi nhuận cao hơn gần như luôn đi kèm rủi ro cao hơn. Ai hứa với anh chị lãi cao mà không có rủi ro, người đó đang không nói hết sự thật.'}, {'k': 'text', 'ch': 'Chương 7 – Đổi phía: từ người gửi thành người chủ', 'cap': ('KHÔNG THẮNG ĐƯỢC', 'THÌ LÀM CHỦ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'stock exchange board', 'say': 'Đến đây, câu hỏi tự nhiên sẽ là: nếu ngân hàng kiếm tiền trên tiền của mình, thì có cách nào để mình hưởng phần chênh lệch đó không? Có một cách, và nó nằm trên sàn chứng khoán. Khi anh chị gửi tiết kiệm, anh chị là người bán tiền cho ngân hàng. Khi anh chị mua cổ phiếu ngân hàng, anh chị trở thành một trong những người chủ của tiệm gạo đó, và được chia phần lời theo tỷ lệ cổ phần. Nghe hấp dẫn, nhưng em sẽ cho anh chị thấy cả hai mặt bằng số, chứ không chỉ mặt đẹp.'}, {'k': 'cards', 'ch': 'Chương 7 – Đổi phía: từ người gửi thành người chủ', 'cap': ('100 ĐỒNG GIÁ', 'KIẾM ĐƯỢC BAO NHIÊU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('Vietcombank: P/E 10,75', '≈ 9,3 đồng lợi nhuận', 'chia tiền mặt ≈ 1,7 đồng'), ('MB: P/E 5,97', '≈ 16,7 đồng lợi nhuận', 'chia tiền mặt ≈ 4,2 đồng'), ('Gửi tiết kiệm 12 tháng', '≈ 6,8 đồng', 'chắc chắn, không mất gốc')], 'say': 'Lấy hệ số giá trên lợi nhuận, P trên E. Vietcombank có P trên E khoảng mười phẩy bảy mươi lăm lần, nghĩa là cứ một trăm đồng anh chị trả cho cổ phiếu, ngân hàng tạo ra khoảng chín phẩy ba đồng lợi nhuận một năm. Nhưng phần chia bằng tiền mặt chỉ khoảng một phẩy bảy đồng, phần còn lại ngân hàng giữ lại để lớn tiếp. MB có P trên E khoảng năm phẩy chín mươi bảy lần, tức là khoảng mười sáu phẩy bảy đồng lợi nhuận trên một trăm đồng giá, và chia tiền mặt khoảng bốn phẩy hai đồng. Còn gửi tiết kiệm, anh chị nhận khoảng sáu phẩy tám đồng, chắc chắn, không mất gốc. Nhìn bảng này, nhiều người sẽ nghĩ ngay rằng mua cổ phiếu ngân hàng lời hơn. Nhưng em xin anh chị đợi một chút. Còn một con số nữa mà bảng lãi suất không bao giờ có.'}, {'k': 'bignum', 'ch': 'Chương 8 – Cái giá của việc làm chủ', 'cap': ('VIETCOMBANK', 'CÁCH ĐỈNH 52 TUẦN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': -30.8, 'fmt': '{:,.1f}', 'unit': '%', 'top': 'ĐỈNH 78,15 – NAY 54,10', 'sub': 'tiết kiệm: gốc không đổi', 'col': (239, 68, 68), 'say': 'Đó là biến động giá. Trong năm mươi hai tuần qua, cổ phiếu Vietcombank có lúc lên khoảng bảy mươi tám phẩy mười lăm nghìn đồng. Nay giá chỉ khoảng năm mươi bốn phẩy mười nghìn đồng, thấp hơn đỉnh khoảng ba mươi phẩy tám phần trăm. Một người mua ở đỉnh với một tỷ đồng, nếu bán hôm nay sẽ còn khoảng sáu trăm chín mươi hai triệu. Trong khi đó, ngân hàng vẫn đang làm ăn có lãi. Đây là điều quan trọng nhất của cả video. Doanh nghiệp tốt chưa chắc là khoản đầu tư tốt nếu mua sai giá. Giá cổ phiếu còn có thể đi ngược với lợi nhuận trong một thời gian dài. Làm chủ thì được chia lời, nhưng cũng phải chịu được những năm giá đi xuống.'}, {'k': 'checklist', 'ch': 'Chương 9 – Bốn câu hỏi trước khi để tiền', 'cap': ('4 CÂU HỎI', 'TRƯỚC KHI ĐỂ TIỀN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'checklist notebook', 'items': [('Đã có quỹ dự phòng 6 tháng chưa?', (34, 197, 94)), ('Tiền này bao lâu nữa mới cần?', (34, 197, 94)), ('CASA, NIM, nợ xấu ngân hàng ra sao?', (255, 196, 0)), ('Giá đã cao hơn lợi nhuận bao nhiêu?', (255, 196, 0))], 'say': 'Vậy anh chị nên để tiền ở đâu? Em không trả lời thay anh chị được, nhưng em gợi ý bốn câu hỏi. Một, anh chị đã có quỹ dự phòng đủ sáu tháng chi tiêu ở dạng tiết kiệm chưa? Phần tiền này nên an toàn trước tiên. Hai, số tiền còn lại bao lâu nữa anh chị mới cần dùng? Tiền cần dùng trong một hai năm tới không nên chịu rủi ro giảm ba mươi phần trăm. Ba, nếu nhìn cổ phiếu ngân hàng, hãy xem ba con số vừa học: tỷ lệ tiền không kỳ hạn, biên lãi thuần và nợ xấu trên dư nợ. Bốn, giá anh chị đang trả cao gấp bao nhiêu lần giá trị sổ sách và lợi nhuận? Mức đó có hợp lý với khả năng sinh lời của ngân hàng không? Bảng số của các ngân hàng trong video được em cập nhật mỗi phiên trên chứng khoán Huy Nguyễn chấm com. Anh chị có thể tự đối chiếu.'}, {'k': 'end', 'cap': ('GỬI TIỀN', 'HAY LÀM CHỦ?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Tóm lại, ngân hàng kiếm tiền từ chênh lệch giữa giá mua tiền và giá bán tiền, và tiền rẻ nhất lại đến từ số dư mà chúng ta để quên trong tài khoản. Người gửi tiền được sự chắc chắn, người làm chủ được phần chênh lệch nhưng phải chịu biến động. Còn anh chị, đang để phần lớn tiền ở phía người gửi hay phía người làm chủ, và vì sao? Anh chị bình luận cho em biết nhé.'}]
